for name, glass in (("M_RmProp_Translucent", False), ("M_RmPropGlass", True), ("M_RmIce", True)):
  ice = name == "M_RmIce"   # Alaska's ice: lit like the glass, evenly see-through (USSXRemasterWorld::RemasteredFor)
  m = recreate(name, unreal.Material, unreal.MaterialFactoryNew())
  if glass:
    # The soft layers of glass and water props (SimData/<track>.surfacelook.txt): lit, a mirror finish, Lumen's
    # front-layer reflections (Remastered post-process volume).
    m.set_editor_property("shading_model", unreal.MaterialShadingModel.MSM_DEFAULT_LIT)
    m.set_editor_property("translucency_lighting_mode", unreal.TranslucencyLightingMode.TLM_SURFACE_PER_PIXEL_LIGHTING)
    if ice:
      # The ice's solid shadow twin lies on the ice itself (USSXRemasterWorld::ApplyTranslucentProps): the sun's shadow is
      # traced with the opaque surfaces' bias, not read as one raw shadow-map sample, which shadowed the ice in patches.
      m.set_editor_property("translucent_directional_light_shadow_quality", 1.0)
  else:
    # Soft layers take the same light as the solid core next to them; unlit, the two showed as different colours.
    m.set_editor_property("shading_model", unreal.MaterialShadingModel.MSM_DEFAULT_LIT)
    m.set_editor_property("translucency_lighting_mode", unreal.TranslucencyLightingMode.TLM_SURFACE_PER_PIXEL_LIGHTING)
    # Lumen's front-layer reflections (a second reflection pass, Epic) are for the mirror layers; rough foliage edges
    # take the radiance-cache reflections of any translucent layer.
    m.set_editor_property("allow_front_layer_translucency", False)
  m.set_editor_property("blend_mode", unreal.BlendMode.BLEND_TRANSLUCENT)
  m.set_editor_property("two_sided", True)
  m.set_editor_property("use_translucency_vertex_fog", True)
  m.set_editor_property("compute_fog_per_pixel", True)
  m.set_editor_property("allow_translucent_custom_depth_writes", True)
  m.set_editor_property("opacity_mask_clip_value", 1.0 / 256.0)
  base = tex_param(m, "BaseTex", -1100, -200)
  uv0 = expr(m, unreal.MaterialExpressionTextureCoordinate, -1700, -200, coordinate_index=0)
  su = expr(m, unreal.MaterialExpressionScalarParameter, -1700, -100, parameter_name="UVScrollU", default_value=0.0)
  sv = expr(m, unreal.MaterialExpressionScalarParameter, -1700, 0, parameter_name="UVScrollV", default_value=0.0)
  suv = expr(m, unreal.MaterialExpressionAppendVector, -1500, -50)
  connect(su, "", suv, "A")
  connect(sv, "", suv, "B")
  uvs = expr(m, unreal.MaterialExpressionAdd, -1300, -150)
  connect(uv0, "", uvs, "A")
  connect(suv, "", uvs, "B")
  connect(uvs, "", base, "UVs")
  vc = expr(m, unreal.MaterialExpressionVertexColor, -1000, 100)
  shade = custom(m, -400, 0, PROP_SOFT_SHADE, F3, [("Tex", (base, "RGB")), ("VC", (vc, ""))], "RmPropSoftShade")
  if glass:
    tint = expr(m, unreal.MaterialExpressionMultiply, -200, -60)
    connect(shade, "", tint, "A")
    connect(expr(m, unreal.MaterialExpressionConstant, -400, -100, r=0.7 if ice else 0.6), "", tint, "B")
    connect_prop(tint, "", unreal.MaterialProperty.MP_BASE_COLOR)
    glow = expr(m, unreal.MaterialExpressionMultiply, -200, 40)
    connect(shade, "", glow, "A")
    connect(expr(m, unreal.MaterialExpressionConstant, -400, 60, r=0.3 if ice else 0.25), "", glow, "B")
    connect_prop(glow, "", unreal.MaterialProperty.MP_EMISSIVE_COLOR)
    connect_prop(expr(m, unreal.MaterialExpressionConstant, -400, 140, r=0.12 if ice else 0.03), "", unreal.MaterialProperty.MP_ROUGHNESS)
    connect_prop(expr(m, unreal.MaterialExpressionConstant, -400, 200, r=0.7 if ice else 1.0), "", unreal.MaterialProperty.MP_SPECULAR)
    water = expr(m, unreal.MaterialExpressionScalarParameter, -700, 260, parameter_name="RmWater", default_value=0.0)
    connect_prop(custom(m, -400, 260, WATER_NORMAL, F3, [("Water", (water, "")), ("WP", (expr(m, unreal.MaterialExpressionWorldPosition, -700, 320), "")),
                                                        ("T", (coll(m, rm, "WorldTime", -700, 380), ""))], "RmWaterNormal"), "",
                 unreal.MaterialProperty.MP_NORMAL)
  else:
    connect_prop(shade, "", unreal.MaterialProperty.MP_BASE_COLOR)
    amb = expr(m, unreal.MaterialExpressionMultiply, -200, 40)
    connect(shade, "", amb, "A")
    connect(coll(m, rm, "BakedAmbient", -400, 60), "", amb, "B")
    connect_prop(amb, "", unreal.MaterialProperty.MP_EMISSIVE_COLOR)
    connect_prop(expr(m, unreal.MaterialExpressionConstant, -400, 140, r=0.7), "", unreal.MaterialProperty.MP_ROUGHNESS)
    connect_prop(expr(m, unreal.MaterialExpressionConstant, -400, 200, r=0.3), "", unreal.MaterialProperty.MP_SPECULAR)
  gs_a = custom(m, -1000, 400, PROP_GS_ALPHA, F1, [("A", (base, "A")), ("VA", (vc, "A"))], "PropGsAlpha")
  if ice:
    alpha = expr(m, unreal.MaterialExpressionConstant, -800, 400, r=0.85)
  else:
    alpha = custom(m, -800, 400, PROP_BLEND.replace("CORE_AS", CORE_AS), F1, [("As", (gs_a, "")), ("Tex", (base, "RGB")), ("VC", (vc, ""))], "PropBlend")
  depth = expr(m, unreal.MaterialExpressionPixelDepth, -700, 500)
  cd = expr(m, unreal.MaterialExpressionSceneTexture, -1000, 650, scene_texture_id=unreal.SceneTextureId.PPI_CUSTOM_DEPTH)
  front = custom(m, -800, 650, SOFT_DEPTH, F1, [("PD", (depth, "")), ("CD", (cd, "Color"))], "SoftDepth")
  vis = expr(m, unreal.MaterialExpressionMultiply, -550, 450)
  connect(alpha, "", vis, "A")
  connect(front, "", vis, "B")
  if glass:
    vis = custom(m, -450, 450, GLASS_OPACITY, F1, [("A", (vis, "")), ("F", (expr(m, unreal.MaterialExpressionFresnel, -650, 380), ""))],
                 "GlassOpacity")
  op = custom(m, -300, 550, DRAW_SOFT, F1,
              [("Depth", (depth, "")), ("DrawDistance", (coll(m, mpc, "DrawDistance", -700, 600), "")),
               ("Scale", (coll(m, rm, "DrawDistanceScale", -700, 660), "")),
               ("UpScale", (coll(m, rm, "DrawDistanceUp", -700, 720), "")),
               ("Rel", (camera_relative(m, -700, 780), "")), ("Alpha", (vis, ""))],
              "DrawClip")
  connect_prop(op, "", unreal.MaterialProperty.MP_OPACITY)
  finish(m)

